#include <bits/stdc++.h>
using namespace std;
int n,m,tim;vector<vector<int>> g;vector<int> d,low;vector<char> cut;void dfs(int u,int p){d[u]=low[u]=++tim;int ch=0;for(int v:g[u]){if(!d[v]){ch++;dfs(v,u);low[u]=min(low[u],low[v]);if(p!=-1&&low[v]>=d[u])cut[u]=1;}else if(v!=p)low[u]=min(low[u],d[v]);}if(p==-1&&ch>1)cut[u]=1;}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);if(!(cin>>n>>m))return 0;g.assign(n+1,{});for(int i=0,u,v;i<m;i++){cin>>u>>v;g[u].push_back(v);g[v].push_back(u);}d.assign(n+1,0);low.assign(n+1,0);cut.assign(n+1,0);for(int i=1;i<=n;i++)if(!d[i])dfs(i,-1);vector<int>a;for(int i=1;i<=n;i++)if(cut[i])a.push_back(i);cout<<a.size()<<endl;for(int i=0;i<(int)a.size();i++){if(i)cout<<' ';cout<<a[i];}return 0;}